using MediatR; using PartyNL.Application.Abstractions.Repositories;
namespace PartyNL.Application.Features.Locations.Commands.UpdateLocation;
public sealed record UpdateLocationCommand(Guid Id,string? Name,string? Street,string? City,string? PostalCode,string? Province,string? Country,decimal Latitude,decimal Longitude):IRequest<UpdateLocationResponse>;
public sealed record UpdateLocationResponse(Guid Id,string? Name,string? Street,string? City,string? PostalCode,string? Province,string? Country,decimal Latitude,decimal Longitude);
public sealed class UpdateLocationHandler(ILocationRepository repository):IRequestHandler<UpdateLocationCommand,UpdateLocationResponse>{public async Task<UpdateLocationResponse> Handle(UpdateLocationCommand request,CancellationToken cancellationToken){var e=await repository.GetByIdAsync(request.Id)??throw new KeyNotFoundException($"Location with ID '{request.Id}' was not found.");e.Name=request.Name;e.Street=request.Street;e.City=request.City;e.PostalCode=request.PostalCode;e.Province=request.Province;e.Country=request.Country;e.Latitude=request.Latitude;e.Longitude=request.Longitude;await repository.UpdateAsync(e);return new(e.Id,e.Name,e.Street,e.City,e.PostalCode,e.Province,e.Country,e.Latitude,e.Longitude);}}